PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_297_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_297_guard;
INSERT INTO _migration_297_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_music_b005_021' AND NOT (q.topic_id IS 'topic_was_music_b005_5' AND q.subject_id IS 'subj_wassce_music' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which musical process is illustrated when a leader sings and a group answers?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Call and response","B. Aerophones","C. It provides a recurring rhythmic reference for the ensemble","D. The simultaneous combination of contrasting rhythmic patterns"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Call and response alternates a lead statement with a communal answer and is central to many Ghanaian performance traditions. Therefore the correct answer is A: Call and response.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_music_b005_5' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_music_b005_021' AND NOT (r.batch_id IS 'wassce-foundation-beta-005' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Music practice aligned to official Ghana curriculum and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_297_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_music_b005_022' AND NOT (q.topic_id IS 'topic_was_music_b005_5' AND q.subject_id IS 'subj_wassce_music' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'To which instrument family does the atenteben belong?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. It provides a recurring rhythmic reference for the ensemble","B. Aerophones","C. The simultaneous combination of contrasting rhythmic patterns","D. Its purpose shapes text, performers, instruments and performance setting"]' AND q.correct_answer IS 'B' AND q.explanation IS 'The atenteben produces sound from a vibrating air column, so organological classification places it among aerophones. Therefore the correct answer is B: Aerophones.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_music_b005_5' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_music_b005_022' AND NOT (r.batch_id IS 'wassce-foundation-beta-005' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Music practice aligned to official Ghana curriculum and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_297_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_music_b005_023' AND NOT (q.topic_id IS 'topic_was_music_b005_5' AND q.subject_id IS 'subj_wassce_music' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the role of a time-line pattern in many African ensembles?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The simultaneous combination of contrasting rhythmic patterns","B. Its purpose shapes text, performers, instruments and performance setting","C. It provides a recurring rhythmic reference for the ensemble","D. Call and response"]' AND q.correct_answer IS 'C' AND q.explanation IS 'A repeated bell or comparable pattern organises entries and interlocking rhythms without replacing every performer’s individual part. Therefore the correct answer is C: It provides a recurring rhythmic reference for the ensemble.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_music_b005_5' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_music_b005_023' AND NOT (r.batch_id IS 'wassce-foundation-beta-005' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Music practice aligned to official Ghana curriculum and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS